def build4(Ypad=185, off=9, Cp=235., L=55, R=200, S=500., ST=2000., K=3., G=20., dz=0.3, vx={0:-0.5,1:-1,2:-1.5,255:1,254:1.5}, vy={1:1.5,2:2.0,3:2.5}, upoff=None):
    W1=np.zeros((128,64),np.float32);b1=np.zeros(64,np.float32)
    W2=np.zeros((64,64),np.float32);b2=np.zeros(64,np.float32)
    W3=np.zeros((64,18),np.float32);b3=np.zeros(18,np.float32)
    n=[0]
    # paddle q = Cp - x70 + off
    def unit(cx, cy, cp, const):  # pre = S/255*(cx*x99 + cy*y101 + cp*q + const)
        j=n[0]; n[0]+=1
        W1[99,j]+=S*cx; W1[101,j]+=S*cy; W1[70,j]+= -S*cp
        b1[j]=S*(const+cp*(Cp+off))/255.
        return j
    th={}
    def thr(byte,t):
        if (byte,t) not in th:
            j=n[0]; n[0]+=1; W1[byte,j]=ST; b1[j]=-ST*t/255; th[(byte,t)]=j
        return th[(byte,t)]
    def rng(byte,lo,hi=None):
        if lo is None: return [(thr(byte,hi),-0.5)],0.5
        if hi is None: return [(thr(byte,lo),0.5)],0.5
        return [(thr(byte,lo),0.5),(thr(byte,hi),-0.5)],0.0
    m=[0]
    def l2pair(f_terms, f_const, gates):
        for sgn in (1,-1):
            j=m[0]; m[0]+=1
            for (i,w) in f_terms: W2[i,j]+=sgn*K*w
            b2[j]+=sgn*K*f_const
            for terms,c in gates:
                for (i,w) in terms: W2[i,j]+=G*w
                b2[j]+=G*(c-1)
            W3[j,11]+=sgn; W3[j,12]-=sgn
    for dyb,vyy in vy.items():
        gdy=rng(103,dyb-0.5,dyb+0.5)
        for dxb,vxx in vx.items():
            r=vxx/vyy; pk=r*Ypad
            a=unit(1,-r,-1,pk)
            bb=unit(-1,r,-1,2*R-pk)
            c=unit(-1,r,-1,2*L-pk)
            if dxb==0: g=rng(105,None,0.5)
            elif dxb==255: g=rng(105,254.5)
            else: g=rng(105,dxb-0.5,dxb+0.5)
            l2pair([(a,1),(bb,1),(c,2)],1.0,[gdy,g])
    uo=0 if upoff is None else upoff
    a0=unit(1,0,-1,-uo)
    l2pair([(a0,1)],0.0,[rng(103,127.5)])
    b3[1]=dz
    print(n[0],m[0])
    return dict(W1=W1,b1=b1,W2=W2,b2=b2,W3=W3,b3=b3)
